import{_ as t,o as e,c as i,aw as o}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"Big-O Notation (сложность алгоритмов)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/algoritms/big-o/info.md","filePath":"wiki/dev-commit/theory/algoritms/big-o/info.md"}'),a={name:"wiki/dev-commit/theory/algoritms/big-o/info.md"};function s(n,l,r,c,p,m){return e(),i("div",null,[...l[0]||(l[0]=[o(`<h1 id="big-o-notation-сложность-алгоритмов" tabindex="-1">Big-O Notation (сложность алгоритмов) <a class="header-anchor" href="#big-o-notation-сложность-алгоритмов" aria-label="Permalink to &quot;Big-O Notation (сложность алгоритмов)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.bigocheatsheet.com/" target="_blank" rel="noreferrer">https://www.bigocheatsheet.com/</a> - Know Thy Complexities!</li><li><a href="https://www.youtube.com/watch?v=ZRdOb4yR0kk" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=ZRdOb4yR0kk</a> - [YouTube] Оценка сложности алгоритма</li><li><a href="https://github.com/dobernike/Interview-tasks/tree/develop/exercises" target="_blank" rel="noreferrer">https://github.com/dobernike/Interview-tasks/tree/develop/exercises</a> - Примеры с GitHub</li></ul></div><h2 id="сложность-алгоритма" tabindex="-1">Сложность алгоритма <a class="header-anchor" href="#сложность-алгоритма" aria-label="Permalink to &quot;Сложность алгоритма&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Big-O Notation</p><ul><li><strong>Big-O Notation</strong> - временная сложность алгоритма</li><li>Показывает <em>верхнюю границу сложности алгоритма</em> зависимости между <em>входными параметрами</em> функции и <em>количеством операций</em>, которые выполнит процессор</li><li>Нельзя оценивать работу алгоритм с точки зрения времени. Один и тот же алгоритм на разных машинах будет выполняться разное время. Алгоритм включает в себя число шагов. Идея Big-O - сколько шагов нужно сделать чтобы алгоритм завершил свое выполнение</li><li>Показывает работу по <em>худшему случаю</em></li></ul></div><div class="tip custom-block"><p class="custom-block-title">Сложность алгоритма</p><ul><li><strong>Сложность алгоритма</strong> (вычислительная сложность) - функция зависимости объёма работы, которая выполняется некоторым алгоритмом, от размера входных данных</li><li>Объём работы обычно измеряется временем и вычислительными ресурсами. Время определяется количеством элементарных шагов, необходимых для решения задачи. Ресурсы определяются объёмом памяти или места на носителе данных</li><li>Сложность алгоритма - насколько быстро растет кол-во операций в зависимости от входных данных</li><li>O(n), где n - кол-во входных данных</li></ul></div><h2 id="time-complexity-и-space-complexity" tabindex="-1">Time Complexity и Space Complexity <a class="header-anchor" href="#time-complexity-и-space-complexity" aria-label="Permalink to &quot;Time Complexity и Space Complexity&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Time Complexity</p><ul><li><strong>Time Complexity</strong> (Временная сложность вычисления) - сколько нужно тиков процессору, чтобы исполнить операции (максимальное кол-во токов, которое подвязано на входные данные, которые участвуют в алгоритмах). Смотрим какой массив значений приходит на вход - он влияет на Time Complexity</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Space Complexity</p><ul><li><strong>Space Complexity</strong> (Пространсвенная сложность вычисления) - вся выделенная память, которая участвуют в алгоритме. Н-р: для уменьшение показателей не нужно создавать новый массив, нужно корректировать существующий</li></ul></div><h2 id="верхняя-граница-отбрасывание-констант" tabindex="-1">Верхняя граница (отбрасывание констант) <a class="header-anchor" href="#верхняя-граница-отбрасывание-констант" aria-label="Permalink to &quot;Верхняя граница (отбрасывание констант)&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">O(N</span><span style="color:#50A14F;"> +</span><span style="color:#50A14F;"> N</span><span style="color:#383A42;">) == O(</span><span style="color:#4078F2;">N</span><span style="color:#383A42;">)</span></span>
<span class="line"><span style="color:#4078F2;">O(N</span><span style="color:#50A14F;"> +</span><span style="color:#986801;"> 1</span><span style="color:#383A42;">) == O(</span><span style="color:#4078F2;">N</span><span style="color:#383A42;">)</span></span>
<span class="line"><span style="color:#4078F2;">O(2N</span><span style="color:#383A42;">)    == O(</span><span style="color:#4078F2;">N</span><span style="color:#383A42;">)</span></span></code></pre></div><ul><li>Мы говорим как будет вести себя алгоритм на бесконечности</li><li>Если алгоритм для n-элементов выполняет n-тактов плюс один такт для вывода информацим на экран, то сложность такого алгоритма всё равно O(N), т.к. бесконечность гораздо больше единицы. Тоже самое касается алгоритмов, которые выполняются за O(2N) или более</li><li>Big-O описывает только скорость роста. Поэтому мы отбрасываем константы при оценке сложности</li><li>Алгоритм, описываемый как O(2N) должен описываться как O(N)</li></ul><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Алгоритм</p><ul><li><strong>Алгоритм</strong> - некоторая последовательность действий, которые необходимо совершить для достижения нужного результата</li></ul></div><ul><li>Книга: Grokking Algorithms</li></ul><h3 id="критерии-алгоритмов" tabindex="-1">Критерии алгоритмов <a class="header-anchor" href="#критерии-алгоритмов" aria-label="Permalink to &quot;Критерии алгоритмов&quot;">​</a></h3><ol><li>Скорость работы</li><li>Память (алгоритм должен использовать разумную дополнительную память)</li><li>Скорость разработки</li></ol><h3 id="_4-асимптотических-нотации" tabindex="-1">4 асимптотических нотации <a class="header-anchor" href="#_4-асимптотических-нотации" aria-label="Permalink to &quot;4 асимптотических нотации&quot;">​</a></h3><ol start="4"><li>О-большое - говорит о том, что один алгоритм, «не хуже» другого</li><li>Омега-большое - говорит о том, что один алгоритм, «не лучше» другого (обратно О-большому)</li><li>Тета-большое - «алгоритмы примерно одинаковы»</li><li>о-малое</li></ol>`,18)])])}const u=t(a,[["render",s]]);export{d as __pageData,u as default};
